"""
WebResearchBridge — creates real research_fn for MicroQueryRunner.
Uses DuckDuckGo for zero-API-key web search.
Falls back to requests-based scraping if DDG fails.
"""

import json
import time
import warnings
from typing import Optional

warnings.filterwarnings("ignore", message=".*renamed.*ddgs.*")

_LAST_CALL_TIME = 0.0
_MIN_DELAY_S = 1.5


def _rate_limit():
    global _LAST_CALL_TIME
    now = time.time()
    elapsed = now - _LAST_CALL_TIME
    if elapsed < _MIN_DELAY_S:
        time.sleep(_MIN_DELAY_S - elapsed)
    _LAST_CALL_TIME = time.time()


def ddg_research(prompt: str) -> str:
    """Research function using DuckDuckGo. Returns raw text for MicroQueryRunner to parse."""
    question = _extract_question(prompt)
    if not question:
        return ""

    _rate_limit()

    try:
        import warnings
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            try:
                from ddgs import DDGS
            except ImportError:
                from duckduckgo_search import DDGS
            with DDGS() as ddgs:
                results = list(ddgs.text(question, max_results=5))
    except Exception:
        results = []

    if not results:
        return _fallback_search(question)

    snippets = []
    for r in results[:5]:
        title = r.get("title", "")
        body = r.get("body", "")
        href = r.get("href", "")
        snippets.append(f"{title}: {body} (source: {href})")

    combined = "\n".join(snippets)

    fact = _extract_fact_from_snippets(combined, question)
    return fact


def _extract_question(prompt: str) -> str:
    """Extract the actual question from the micro-query prompt template."""
    lines = prompt.strip().split("\n")
    for line in lines:
        if line.startswith("Question:"):
            return line.replace("Question:", "").strip()
    for line in lines:
        if "?" in line and not line.startswith("Format:") and not line.startswith("Rules:"):
            return line.strip()
    return prompt[:200]


def _extract_fact_from_snippets(text: str, question: str) -> str:
    """Convert search snippets into structured fact JSON for MicroQueryRunner.
    Picks the MOST RELEVANT snippet to the question, not just the first one.
    Applies relevance penalty when snippet doesn't answer the question.
    """
    import re

    snippets = text.split("\n")
    best_snippet, best_relevance = _pick_best_snippet(snippets, question)

    numbers = re.findall(r'[\d,.]+%|[$€£]\s*[\d,.]+[KMBkmb]?|\d{1,3}(?:,\d{3})*(?:\.\d+)?', best_snippet)
    first_url = ""
    url_match = re.search(r'source:\s*(https?://[^\s\)]+)', best_snippet)
    if not url_match:
        url_match = re.search(r'source:\s*(https?://[^\s\)]+)', text)
    if url_match:
        first_url = url_match.group(1)

    value = numbers[0] if numbers else None
    confidence = _score_confidence(best_snippet, first_url, numbers)
    # Relevance penalty only for poor matches (<0.6), not for good ones
    if best_relevance < 0.6:
        confidence = round(confidence * (0.5 + best_relevance), 2)
    else:
        confidence = round(confidence, 2)

    fact_json = {
        "fact": best_snippet[:200],
        "value": value,
        "confidence": confidence,
        "source": first_url or "duckduckgo_search",
        "date": None,
    }

    return json.dumps(fact_json, ensure_ascii=False)


def _pick_best_snippet(snippets: list[str], question: str) -> tuple[str, float]:
    """Score each snippet by keyword overlap with question. Return best + relevance score."""
    q_terms = _extract_keywords(question)
    if not q_terms or not snippets:
        combined = "\n".join(snippets)[:300]
        return combined, 0.5

    best_text = snippets[0] if snippets else ""
    best_score = 0.0

    for snippet in snippets:
        if not snippet.strip():
            continue
        s_lower = snippet.lower()
        hits = sum(1 for t in q_terms if t in s_lower)
        score = hits / len(q_terms)
        if score > best_score:
            best_score = score
            best_text = snippet

    relevance = min(1.0, 0.5 + best_score * 0.5) if best_score > 0 else 0.4
    return best_text[:300], relevance


def _extract_keywords(text: str) -> list[str]:
    """Extract meaningful keywords from a question, ignoring stop words."""
    stop = {
        "what", "how", "is", "the", "a", "an", "in", "of", "for", "to", "and",
        "or", "are", "was", "were", "be", "been", "do", "does", "did", "will",
        "can", "could", "should", "would", "may", "might", "much", "many",
        "typical", "common",
    }
    import re
    words = re.findall(r'[a-zA-Z]{3,}', text.lower())
    return [w for w in words if w not in stop]


_AUTHORITY_DOMAINS = {
    ".gov": 0.15, ".edu": 0.12, "who.int": 0.12, "worldbank.org": 0.12,
    "statista.com": 0.10, "crunchbase.com": 0.08, "pitchbook.com": 0.08,
    "dealstreetasia.com": 0.08, "techcrunch.com": 0.06, "reuters.com": 0.08,
    "bloomberg.com": 0.08, "wikipedia.org": 0.05, "linkedin.com": 0.04,
}


def _score_confidence(text: str, url: str, numbers: list) -> float:
    score = 0.35
    if numbers:
        score += 0.15
    if len(numbers) >= 3:
        score += 0.10
    url_lower = url.lower()
    for domain, boost in _AUTHORITY_DOMAINS.items():
        if domain in url_lower:
            score += boost
            break
    if any(w in text.lower() for w in ["according to", "reported", "data shows", "survey", "study"]):
        score += 0.05
    import re
    if re.search(r'\b20[12]\d\b', text):
        score += 0.05
    return min(0.90, round(score, 2))


def _fallback_search(question: str) -> str:
    """Fallback: use requests to hit DuckDuckGo HTML directly."""
    import requests
    try:
        resp = requests.get(
            "https://html.duckduckgo.com/html/",
            params={"q": question},
            headers={"User-Agent": "Mozilla/5.0"},
            timeout=10,
        )
        if resp.status_code == 200:
            text = resp.text[:2000]
            import re
            snippets = re.findall(r'class="result__snippet">(.*?)</a>', text)
            if snippets:
                combined = " ".join(s[:100] for s in snippets[:3])
                return json.dumps({
                    "fact": combined[:200],
                    "value": None,
                    "confidence": 0.35,
                    "source": "duckduckgo_html_fallback",
                    "date": None,
                }, ensure_ascii=False)
    except Exception:
        pass
    return ""


def create_research_fn(delay_s: float = 1.5) -> callable:
    """Factory: creates a rate-limited research function."""
    global _MIN_DELAY_S
    _MIN_DELAY_S = delay_s
    return ddg_research

"""Provider factory for easy instantiation from config."""

import json
import os
from pathlib import Path
from typing import Optional

from .provider_interface import LLMProvider, ProviderConfig
from .providers import ClaudeProvider, OpenAIProvider, GeminiProvider, OllamaProvider


PROVIDER_CLASSES = {
    "claude": ClaudeProvider,
    "openai": OpenAIProvider,
    "gemini": GeminiProvider,
    "ollama": OllamaProvider,
}

DEFAULT_CONFIG_PATH = Path(__file__).parent.parent.parent / "data" / "llm-config.json"


def load_config(config_path: Optional[Path] = None) -> dict:
    """Load LLM configuration from JSON file."""
    path = config_path or DEFAULT_CONFIG_PATH
    if not path.exists():
        raise FileNotFoundError(f"LLM config not found: {path}")
    with open(path) as f:
        return json.load(f)


def create_provider(name: str, config: Optional[dict] = None) -> LLMProvider:
    """Create a provider instance by name."""
    if name not in PROVIDER_CLASSES:
        raise ValueError(f"Unknown provider: {name}. Available: {list(PROVIDER_CLASSES.keys())}")

    full_config = load_config() if config is None else config
    provider_config = full_config.get("providers", {}).get(name, {})

    if not provider_config.get("enabled", False):
        raise ValueError(f"Provider '{name}' is disabled in config")

    api_key_env = provider_config.get("api_key_env", "")
    api_key = os.environ.get(api_key_env, "") if api_key_env else ""

    if name != "ollama" and not api_key:
        raise ValueError(f"API key not found for provider '{name}'. Set {api_key_env} env var.")

    model = provider_config.get("default_model")
    if not model:
        raise ValueError(f"No default_model configured for provider '{name}'")

    pconfig = ProviderConfig(
        api_key=api_key,
        model=model,
        max_tokens=provider_config.get("max_tokens", 4096),
        timeout_seconds=provider_config.get("timeout_seconds", 120),
        base_url=provider_config.get("base_url"),
    )

    return PROVIDER_CLASSES[name](pconfig)


def get_default_provider(config: Optional[dict] = None) -> LLMProvider:
    """Get the default provider from config."""
    full_config = config or load_config()
    default_name = full_config.get("default_provider", "claude")
    return create_provider(default_name, full_config)


def get_fallback_chain(config: Optional[dict] = None) -> list[LLMProvider]:
    """Get ordered list of fallback providers."""
    full_config = config or load_config()
    chain = full_config.get("fallback_chain", ["claude"])
    providers = []

    for name in chain:
        try:
            providers.append(create_provider(name, full_config))
        except (ValueError, ImportError):
            continue

    return providers


def complete_with_fallback(prompt: str, config: Optional[dict] = None, **kwargs) -> "CompletionResult":
    """Complete with automatic fallback on failure."""
    from .provider_interface import CompletionResult

    providers = get_fallback_chain(config)
    if not providers:
        raise RuntimeError("No providers available in fallback chain")

    last_error = None
    for provider in providers:
        try:
            return provider.complete(prompt, **kwargs)
        except Exception as e:
            last_error = e
            continue

    raise RuntimeError(f"All providers failed. Last error: {last_error}")

"""Capability-based routing for LLM provider selection."""

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Optional

from .provider_interface import LLMProvider
from .factory import PROVIDER_CLASSES, create_provider, load_config


@dataclass
class RouteDecision:
    provider_name: str
    model: str
    reason: str
    cost_estimate: float
    fallback_chain: list[str]


DEFAULT_MATRIX_PATH = Path(__file__).parent.parent / "data" / "capability-matrix.json"
DEFAULT_RULES_PATH = Path(__file__).parent.parent / "data" / "routing-rules.json"


class CapabilityRouter:
    """Route tasks to optimal LLM provider based on capability and cost."""

    def __init__(
        self,
        matrix_path: Optional[Path] = None,
        rules_path: Optional[Path] = None,
        providers: Optional[dict[str, LLMProvider]] = None,
    ):
        self.matrix_path = matrix_path or DEFAULT_MATRIX_PATH
        self.rules_path = rules_path or DEFAULT_RULES_PATH
        self.matrix = self._load_matrix()
        self.rules = self._load_rules()
        self._providers = providers or {}

    def _load_matrix(self) -> dict:
        if self.matrix_path.exists():
            with open(self.matrix_path) as f:
                return json.load(f)
        return self._default_matrix()

    def _load_rules(self) -> dict:
        if self.rules_path.exists():
            with open(self.rules_path) as f:
                return json.load(f)
        return self._default_rules()

    def _default_matrix(self) -> dict:
        return {
            "task_types": {
                "deep_analysis": {
                    "required_capabilities": ["reasoning", "long_context"],
                    "preferred_providers": ["claude-opus", "gpt-4o", "gemini-2.5-pro"],
                    "max_cost_per_1k_tokens": 0.05,
                },
                "code_generation": {
                    "required_capabilities": ["code", "structured_output"],
                    "preferred_providers": ["claude-sonnet", "gpt-4o-mini", "gemini-2.5-flash"],
                    "max_cost_per_1k_tokens": 0.02,
                },
                "simple_qa": {
                    "required_capabilities": ["basic"],
                    "preferred_providers": ["ollama", "claude-haiku", "gemini-2.0-flash"],
                    "max_cost_per_1k_tokens": 0.001,
                },
                "vision": {
                    "required_capabilities": ["vision"],
                    "preferred_providers": ["claude-sonnet", "gpt-4o", "gemini-2.5-pro"],
                    "max_cost_per_1k_tokens": 0.03,
                },
                "default": {
                    "required_capabilities": [],
                    "preferred_providers": ["claude-sonnet", "gpt-4o-mini"],
                    "max_cost_per_1k_tokens": 0.02,
                },
            },
            "provider_capabilities": {
                "claude-opus": ["reasoning", "code", "vision", "long_context", "structured_output"],
                "claude-sonnet": ["reasoning", "code", "vision", "long_context", "structured_output"],
                "claude-haiku": ["code", "vision", "structured_output"],
                "gpt-4o": ["reasoning", "code", "vision", "long_context", "structured_output"],
                "gpt-4o-mini": ["code", "vision", "structured_output"],
                "gemini-2.5-pro": ["reasoning", "code", "vision", "long_context", "structured_output"],
                "gemini-2.5-flash": ["reasoning", "code", "vision", "long_context", "structured_output"],
                "gemini-2.0-flash": ["code", "vision", "long_context", "structured_output"],
                "ollama": ["code", "structured_output"],
            },
        }

    def _default_rules(self) -> dict:
        return {
            "overrides": {
                "user_preference": None,
                "cost_mode": "balanced",
                "fallback_enabled": True,
            },
            "blocklist": [],
            "force_local": ["intent_classification", "complexity_scoring", "pattern_lookup"],
        }

    def route(self, task_type: str, context: Optional[dict] = None) -> RouteDecision:
        context = context or {}

        if task_type in self.rules.get("force_local", []):
            return RouteDecision(
                provider_name="local",
                model="local",
                reason="Task forced to local processing",
                cost_estimate=0.0,
                fallback_chain=[],
            )

        if self.rules.get("overrides", {}).get("user_preference"):
            pref = self.rules["overrides"]["user_preference"]
            if pref not in self.rules.get("blocklist", []):
                return RouteDecision(
                    provider_name=pref,
                    model=self._get_model_for_provider(pref),
                    reason="User preference override",
                    cost_estimate=self._estimate_cost(pref, context),
                    fallback_chain=self._build_fallback_chain(task_type, exclude=[pref]),
                )

        task_config = self.matrix.get("task_types", {}).get(task_type)
        if not task_config:
            task_config = self.matrix.get("task_types", {}).get("default", {})

        preferred = task_config.get("preferred_providers", [])
        required_caps = set(task_config.get("required_capabilities", []))
        max_cost = task_config.get("max_cost_per_1k_tokens", 1.0)

        for provider_name in preferred:
            if provider_name in self.rules.get("blocklist", []):
                continue

            provider_caps = set(self.matrix.get("provider_capabilities", {}).get(provider_name, []))
            if required_caps and not required_caps.issubset(provider_caps):
                continue

            cost = self._estimate_cost(provider_name, context)
            if cost > max_cost * context.get("estimated_tokens", 1000) / 1000:
                if self.rules.get("overrides", {}).get("cost_mode") == "strict":
                    continue

            return RouteDecision(
                provider_name=provider_name,
                model=self._get_model_for_provider(provider_name),
                reason=f"Best match for {task_type} with capabilities {required_caps}",
                cost_estimate=cost,
                fallback_chain=self._build_fallback_chain(task_type, exclude=[provider_name]),
            )

        return RouteDecision(
            provider_name="claude-sonnet",
            model="claude-sonnet-4-6",
            reason="Default fallback",
            cost_estimate=self._estimate_cost("claude-sonnet", context),
            fallback_chain=["gpt-4o-mini", "gemini-2.0-flash"],
        )

    def _get_model_for_provider(self, provider_name: str) -> str:
        models = {
            "claude-opus": "claude-opus-4-5",
            "claude-sonnet": "claude-sonnet-4-6",
            "claude-haiku": "claude-haiku-4-5",
            "gpt-4o": "gpt-4o",
            "gpt-4o-mini": "gpt-4o-mini",
            "gemini-2.5-pro": "gemini-2.5-pro",
            "gemini-2.5-flash": "gemini-2.5-flash",
            "gemini-2.0-flash": "gemini-2.0-flash",
            "ollama": "llama3.2",
        }
        return models.get(provider_name, provider_name)

    def _estimate_cost(self, provider_name: str, context: dict) -> float:
        costs_per_1k = {
            "claude-opus": 0.045,
            "claude-sonnet": 0.009,
            "claude-haiku": 0.0024,
            "gpt-4o": 0.01,
            "gpt-4o-mini": 0.0004,
            "gemini-2.5-pro": 0.006,
            "gemini-2.5-flash": 0.0004,
            "gemini-2.0-flash": 0.0,
            "ollama": 0.0,
        }
        tokens = context.get("estimated_tokens", 1000)
        return costs_per_1k.get(provider_name, 0.01) * tokens / 1000

    def _build_fallback_chain(self, task_type: str, exclude: list[str]) -> list[str]:
        task_config = self.matrix.get("task_types", {}).get(task_type, {})
        preferred = task_config.get("preferred_providers", [])
        return [p for p in preferred if p not in exclude and p not in self.rules.get("blocklist", [])][:3]

    def get_provider(self, decision: RouteDecision) -> Optional[LLMProvider]:
        if decision.provider_name == "local":
            return None

        if decision.provider_name in self._providers:
            return self._providers[decision.provider_name]

        provider_map = {
            "claude-opus": "claude",
            "claude-sonnet": "claude",
            "claude-haiku": "claude",
            "gpt-4o": "openai",
            "gpt-4o-mini": "openai",
            "gemini-2.5-pro": "gemini",
            "gemini-2.5-flash": "gemini",
            "gemini-2.0-flash": "gemini",
            "ollama": "ollama",
        }

        base_provider = provider_map.get(decision.provider_name)
        if base_provider:
            try:
                return create_provider(base_provider)
            except (ValueError, ImportError):
                pass

        return None

"""Abstract base class and data structures for LLM providers."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Optional
import time


@dataclass
class ProviderConfig:
    """Configuration for an LLM provider."""
    api_key: str
    model: str
    max_tokens: int = 4096
    temperature: float = 0.7
    timeout_seconds: int = 120
    base_url: Optional[str] = None

    def __repr__(self) -> str:
        key_display = f"{self.api_key[:4]}...{self.api_key[-4:]}" if len(self.api_key) > 8 else "[REDACTED]"
        return f"ProviderConfig(api_key='{key_display}', model='{self.model}')"


@dataclass
class CompletionResult:
    """Normalized response from any LLM provider."""
    content: str
    model: str
    tokens_in: int
    tokens_out: int
    cost_usd: float
    latency_ms: int
    provider: str
    metadata: dict = field(default_factory=dict)

    @property
    def total_tokens(self) -> int:
        return self.tokens_in + self.tokens_out


class LLMProvider(ABC):
    """Abstract base class for LLM providers."""

    PROVIDER_NAME: str = "base"

    def __init__(self, config: ProviderConfig):
        self.config = config
        self._client = None

    @abstractmethod
    def _init_client(self) -> None:
        """Initialize the provider-specific client."""
        pass

    @abstractmethod
    def complete(self, prompt: str, **kwargs) -> CompletionResult:
        """Generate a completion for the given prompt."""
        pass

    @abstractmethod
    def get_capabilities(self) -> dict:
        """Return provider capabilities (reasoning, code, vision, etc.)."""
        pass

    @abstractmethod
    def get_cost_per_token(self) -> dict:
        """Return cost per 1K tokens for input/output."""
        pass

    def health_check(self) -> bool:
        """Check if provider is available. Default: try a minimal completion."""
        try:
            result = self.complete("Say 'ok'", max_tokens=5)
            return len(result.content) > 0
        except Exception:
            return False

    def _measure_latency(self, func, *args, **kwargs):
        """Wrapper to measure execution time in milliseconds."""
        start = time.perf_counter()
        result = func(*args, **kwargs)
        latency_ms = int((time.perf_counter() - start) * 1000)
        return result, latency_ms

    def _calculate_cost(self, tokens_in: int, tokens_out: int) -> float:
        """Calculate cost in USD based on token counts."""
        costs = self.get_cost_per_token()
        cost_in = (tokens_in / 1000) * costs.get("input", 0)
        cost_out = (tokens_out / 1000) * costs.get("output", 0)
        return round(cost_in + cost_out, 6)

