"""Tests for MentalModelLoader — auto-detection of which MMs fire."""

import pytest

from ..mental_model_loader import MentalModelLoader, MatchedModel


@pytest.fixture
def loader():
    return MentalModelLoader()


class TestAlwaysOnModels:
    def test_business_query_fires_mm04_mm06_mm09_mm11(self, loader):
        matched = loader.match(
            query_type="opportunity",
            query_text="How to build SaaS for restaurants",
            dim_scores={},
        )
        ids = {m.id for m in matched}
        assert "MM-04" in ids, "Munger inversion should always fire before verdict"
        assert "MM-06" in ids, "CENTS should fire on business queries"
        assert "MM-09" in ids, "Follow The Money should fire on business queries"
        assert "MM-11" in ids, "Cross-Domain Pattern Match should fire"

    def test_mm18_fires_before_recommendation(self, loader):
        matched = loader.match(
            query_type="opportunity",
            query_text="How to enter coffee export",
            dim_scores={},
            is_pre_verdict=True,
        )
        ids = {m.id for m in matched}
        assert "MM-18" in ids, "Money-Flow Trace is BLOCKING before recommendation"

    def test_technical_query_skips_business_models(self, loader):
        matched = loader.match(
            query_type="technical",
            query_text="How to optimize database queries",
            dim_scores={},
        )
        ids = {m.id for m in matched}
        assert "MM-06" not in ids
        assert "MM-09" not in ids


class TestExternalSourceTriggers:
    def test_external_source_fires_mm07_mm17(self, loader):
        matched = loader.match(
            query_type="opportunity",
            query_text="Analyze this article about a successful founder",
            dim_scores={},
            has_external_source=True,
        )
        ids = {m.id for m in matched}
        assert "MM-07" in ids, "Cui Bono fires on external sources"
        assert "MM-17" in ids, "Article Narrative Firewall fires on external sources"

    def test_no_external_source_skips_mm07(self, loader):
        matched = loader.match(
            query_type="opportunity",
            query_text="How to build SaaS",
            dim_scores={},
            has_external_source=False,
        )
        ids = {m.id for m in matched}
        assert "MM-07" not in ids


